<?php
declare(strict_types=1);
require_once __DIR__.'/seguridad.php';$student=simceRequireStudent();$db=simceDatabase();if(($_SERVER['REQUEST_METHOD']??'')!=='POST')simceJson(array('ok'=>false,'error'=>'Método no permitido.'),405);$d=simceReadJson(1048576);$tid=(int)($d['pruebaId']??0);$q=$db->prepare('SELECT p.id FROM pruebas p JOIN asignaciones x ON x.prueba_id=p.id AND x.colegio_id=p.colegio_id WHERE p.id=:p AND x.curso_id=:c AND p.colegio_id=:school AND p.activa=1 AND x.activa=1');$q->execute(array(':p'=>$tid,':c'=>$student['curso_id'],':school'=>$student['colegio_id']));if(!$q->fetch())simceJson(array('ok'=>false,'error'=>'Prueba no asignada.'),403);$correct=max(0,(int)($d['correct']??0));$total=max(1,(int)($d['total']??0));if($correct>$total)simceJson(array('ok'=>false,'error'=>'Resultado inválido.'),400);$n=$db->prepare('SELECT COALESCE(MAX(intento),0)+1 FROM resultados WHERE colegio_id=:s AND alumno_id=:a AND prueba_id=:p');$n->execute(array(':s'=>$student['colegio_id'],':a'=>$student['id'],':p'=>$tid));$attempt=(int)$n->fetchColumn();$i=$db->prepare('INSERT INTO resultados(colegio_id,alumno_id,prueba_id,intento,correctas,total,puntaje,puntaje_max,porcentaje,nota,respuestas_json,iniciado_at,ip)VALUES(:school,:a,:p,:i,:c,:t,:score,:max,:pct,:nota,:r,:start,:ip)');$i->execute(array(':school'=>$student['colegio_id'],':a'=>$student['id'],':p'=>$tid,':i'=>$attempt,':c'=>$correct,':t'=>$total,':score'=>(float)($d['puntaje']??$correct),':max'=>max(.01,(float)($d['puntajeMax']??$total)),':pct'=>min(100,max(0,(float)($d['pct']??$correct/$total*100))),':nota'=>isset($d['notaNum'])?(float)$d['notaNum']:null,':r'=>json_encode($d['detalles']??array(),JSON_UNESCAPED_UNICODE),':start'=>date('Y-m-d H:i:s',(int)($_SESSION['prueba_inicio']??time())),':ip'=>simceClientIp()));simceJson(array('ok'=>true,'intento'=>$attempt));

